/**
 * Synthetic Rippling payslip text in the `pdf-parse` output shape (glued labels/amounts, header block last).
 * Fictional values only — never copy figures from a real stub.
 */
export type RipplingFixtureOpts = {
  earnings?: string[];
  taxes?: string[];
  summary?: string[];
  deposits?: string[];
  extraBody?: string[];
  payPeriod?: string;
  payDate?: string;
  headerGross?: string;
  headerNet?: string;
};

export const BASE_EARNINGS = ["Salary - 40 $5,000.00 80 $10,000.00 "];
export const BASE_TAXES = [
  "Social Security Tax - Employee$310.00$620.00",
  "Federal Income Tax$900.00$1,800.00",
  "Medicare Tax - Employee$72.50$145.00"
];
export const BASE_SUMMARY = ["Gross Pay$5,000.00$10,000.00", "Deductions$0.00$0.00", "Taxes$1,282.50$2,565.00", "Net Pay$3,717.50$7,435.00"];
export const BASE_DEPOSITS = ["Acct# ...111 Trace:", "000000000000001", "$3,217.50", "Acct# ...222 Trace:", "000000000000002", "$500.00"];

export function ripplingPayslipText(o: RipplingFixtureOpts = {}): string {
  return [
    "",
    "",
    "TIME OFFUSEDACCRUEDBALANCE",
    "US PTO 0.00 hours-Unlimited",
    "US Sick Leave 0.00 hours-Unlimited",
    "EARNINGSRATECURRENT",
    "HOURS",
    "CURRENT",
    "PERIOD",
    "YTD HOURSYTD",
    "AMOUNT",
    ...(o.earnings ?? BASE_EARNINGS),
    "EMPLOYEE TAXESCURRENT PERIODYTD AMOUNT",
    ...(o.taxes ?? BASE_TAXES),
    ...(o.extraBody ?? []),
    "SUMMARYCURRENTYTD",
    ...(o.summary ?? BASE_SUMMARY),
    ...(o.deposits ?? BASE_DEPOSITS),
    "EARNINGS STATEMENT ",
    "EMPLOYER:",
    "Acme Corp ",
    "(Legal Address)",
    "100 Example Way",
    "Springfield, Illinois 62701",
    "Phone: +1 (555) 010-0000",
    "PAID TO:",
    "Jane Doe",
    "1 Test Street",
    "Springfield, Illinois 62701",
    "SSN: ...0000",
    "ADVICE OF DEPOSIT",
    "PAY PERIOD:",
    o.payPeriod ?? "06/01/2026 - 06/15/2026",
    "PAY DATE:",
    o.payDate ?? "06/15/2026",
    "GROSS PAY:",
    o.headerGross ?? "$5,000.00",
    "NET PAY:",
    o.headerNet ?? "$3,717.50",
    "THIS IS NOT A CHECK",
    "Paystub generated by ",
    "PAYSTUB ID: abc123def456 www.rippling.com"
  ].join("\n");
}
